begin;
lock table public.clinical_guidelines in share mode;
lock table public.guideline_versions in share row exclusive mode;
create temporary table population_batch on commit drop as
select * from jsonb_to_recordset($population$[{"id":"b2e88f9f-f504-436b-b521-b20ae8767b15","title":"Acute Poisoning and Overdose","original_version_id":"b2e88f9f-f504-436b-b521-b20ae8767b15","expected_hash":"9b933da63c71b533feeda32f4b9e1937","source_url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","source_title":"Resuscitation Council UK 2025 Special Circumstances Guidelines","issuer":"Other","scope":"Adults in cardiac arrest or peri-arrest where poisoning is suspected; this extraction is limited to resuscitation priorities and poison-centre escalation.","content":{"id":"b2e88f9f-f504-436b-b521-b20ae8767b15","title":"Acute Poisoning and Overdose","specialty":"Emergency Medicine / Toxicology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Toxicity depends on the substance, dose, formulation, time, co-ingestants, and host physiology. Absorption and metabolism may cause delayed injury, and initially reassuring observations do not exclude later deterioration. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Toxicity depends on the substance, dose, formulation, time, co-ingestants, and host physiology. Absorption and metabolism may cause delayed injury, and initially reassuring observations do not exclude later deterioration.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Acute Poisoning and Overdose, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Airway compromise or respiratory depression","Seizure, dysrhythmia, shock, or severe acidosis","Hyperthermia or rapidly changing consciousness","High-risk caustic/cardiotoxic exposure or delayed-release ingestion"]},"differentials":[{"condition":"Stroke/sepsis/metabolic encephalopathy","distinguishingFeatures":"May mimic intoxication and require parallel evaluation."},{"condition":"Trauma after collapse","distinguishingFeatures":"Look for occult injury."},{"condition":"Withdrawal","distinguishingFeatures":"Timing and substance history distinguish toxicity from withdrawal."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Bedside glucose, ECG, vital-sign trends, and targeted laboratory tests based on exposure and toxidrome.","modalityTarget":"Bedside glucose, ECG, vital-sign trends, and targeted laboratory tests based on exposure and toxidrome. — Acute Poisoning and Overdose","targetCondition":"Acute Poisoning and Overdose","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Contact regional poison centre or toxicologist; broad screening should not replace focused assessment.","modalityTarget":"Contact regional poison centre or toxicologist; broad screening should not replace focused assessment. — Cause, complication, or risk relevant to Acute Poisoning and Overdose","targetCondition":"Cause, complication, or risk relevant to Acute Poisoning and Overdose","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Acute Poisoning and Overdose","targetCondition":"Important alternative to Acute Poisoning and Overdose","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults in cardiac arrest or peri-arrest where poisoning is suspected; this extraction is limited to resuscitation priorities and poison-centre escalation. The source does not provide a complete toxin-specific investigation set, antidote doses, routes, frequencies, durations or contraindications. Obtain poison-centre advice and reconcile with Saudi toxicology and formulary protocols before approval. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"9fcbd16b-3164-48b3-8ef4-79568e8801d7","title":"Resuscitation Council UK 2025 Special Circumstances Guidelines","issuer":"Other","edition":"2025 Resuscitation Guidelines","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","locator":"Toxins section","primary_source":true}],"selection_rationale":"Unverified scope: Adults in cardiac arrest or peri-arrest where poisoning is suspected; this extraction is limited to resuscitation priorities and poison-centre escalation."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"ABCDE assessment with continuous physiological monitoring","clinical_question":"Is there immediately reversible airway, breathing, circulation or neurological compromise?","expected_finding":"Clinical instability or a toxidrome may identify urgent supportive priorities.","decision_rationale":"The guideline directs structured assessment and correction of reversible causes in toxic cardiac arrest.","timeframe":"Immediately"},{"test":"Toxin identification and poison-centre consultation","clinical_question":"Which toxic agent, dose, timing and specific treatment are relevant?","expected_finding":"Agent-specific advice may identify antidotes, decontamination or enhanced elimination.","decision_rationale":"The guideline directs consultation with a regional or national poison centre.","timeframe":"As soon as poisoning is suspected"}],"evidence":{"sources":[{"id":"9fcbd16b-3164-48b3-8ef4-79568e8801d7","title":"Resuscitation Council UK 2025 Special Circumstances Guidelines","issuer":"Other","edition":"2025 Resuscitation Guidelines","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","locator":"Toxins section","primary_source":true}],"selection_rationale":"Unverified scope: Adults in cardiac arrest or peri-arrest where poisoning is suspected; this extraction is limited to resuscitation priorities and poison-centre escalation."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Ensure responder safety and avoid direct exposure to potentially transmissible toxic agents.","timeframe":"Before and during resuscitation"},{"instruction":"Reduce further absorption and consider antidotes, decontamination and enhanced elimination only with agent-specific expert advice.","timeframe":"As soon as feasible"},{"instruction":"Prepare for prolonged resuscitation because toxin concentration may fall during metabolism or elimination.","timeframe":"During ongoing resuscitation"},{"instruction":"Review gaps: The source does not provide a complete toxin-specific investigation set, antidote doses, routes, frequencies, durations or contraindications. Obtain poison-centre advice and reconcile with Saudi toxicology and formulary protocols before approval.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"9fcbd16b-3164-48b3-8ef4-79568e8801d7","title":"Resuscitation Council UK 2025 Special Circumstances Guidelines","issuer":"Other","edition":"2025 Resuscitation Guidelines","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","locator":"Toxins section","primary_source":true}],"selection_rationale":"Unverified scope: Adults in cardiac arrest or peri-arrest where poisoning is suspected; this extraction is limited to resuscitation priorities and poison-centre escalation."}}]},"nonClinicalManagement":{"patientEducation":["Explain acute poisoning and overdose in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Emergency Medicine / Toxicology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"c2c404f2-5f47-4e4d-9ce7-fb32a9c1e101","title":"Acute Severe Asthma Exacerbation","original_version_id":"c2c404f2-5f47-4e4d-9ce7-fb32a9c1e101","expected_hash":"68af3ffcab5823479ee17a573cb44a9a","source_url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","source_title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","scope":"Adults and young people who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review.","content":{"id":"c2c404f2-5f47-4e4d-9ce7-fb32a9c1e101","title":"Acute Severe Asthma Exacerbation","specialty":"Emergency Medicine","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Airway inflammation, bronchoconstriction, and mucus cause acute variable airflow obstruction.","keyMechanisms":["Bronchial smooth-muscle constriction","Mucosal edema and inflammation","Mucus plugging","Air trapping and ventilation-perfusion mismatch"]},"presentation":{"symptoms":["Worsening dyspnea","Wheeze","Cough","Chest tightness","Reduced ability to speak or perform usual activity"],"physicalSigns":["Tachypnea","Prolonged expiration","Wheeze or reduced air entry","Accessory muscle use","Reduced oxygen saturation"],"redFlags":["Silent chest","Exhaustion or altered consciousness","Cyanosis or severe hypoxemia","Poor respiratory effort","Hypotension or possible anaphylaxis"]},"differentials":[{"condition":"Anaphylaxis","distinguishingFeatures":"Respiratory symptoms with urticaria, angioedema, hypotension, or likely allergen exposure."},{"condition":"COPD exacerbation","distinguishingFeatures":"Chronic airflow symptoms with relevant smoking or exposure history."},{"condition":"Pneumonia","distinguishingFeatures":"Fever, focal chest findings, or compatible infiltrate."},{"condition":"Pulmonary embolism","distinguishingFeatures":"Sudden dyspnea or pleuritic pain with thromboembolic risk."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Peak expiratory flow or FEV1 when safe","modalityTarget":"Peak expiratory flow or FEV1 when safe — Airflow obstruction","targetCondition":"Airflow obstruction","expectedFinding":"Reduced expiratory flow compared with predicted or personal best.","clinicalRationale":"Objective severity measure and response assessment; do not delay treatment."},{"tier":"laboratory","testName":"Pulse oximetry","modalityTarget":"Pulse oximetry — Hypoxemia","targetCondition":"Hypoxemia","expectedFinding":"Reduced oxygen saturation when hypoxemic.","clinicalRationale":"Guides oxygen and monitoring."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Chest radiograph when complications or alternative diagnosis suspected","modalityTarget":"Chest radiograph when complications or alternative diagnosis suspected — Pneumothorax or focal pneumonia","targetCondition":"Pneumothorax or focal pneumonia","expectedFinding":"No alternative acute thoracic abnormality in uncomplicated asthma.","clinicalRationale":"Imaging is selective and not routinely required."},{"tier":"specializedAdjunctive","testName":"12-lead ECG when cardiac symptoms or risks are present","modalityTarget":"12-lead ECG when cardiac symptoms or risks are present — Acute cardiac cause of dyspnea","targetCondition":"Acute cardiac cause of dyspnea","expectedFinding":"No acute ischemic or significant rhythm abnormality when not causal.","clinicalRationale":"Assesses important mimics or complications."}]},"clinicalManagement":[{"id":"triage-stabilize","title":"Triage and stabilize","timeframe":"Immediately","actions":["Assess airway, breathing, circulation, mental status, observations, and oxygen saturation.","Begin acute asthma treatment under current local protocol without waiting for tests.","Summon senior or resuscitation support for severe features."],"branches":[{"condition":"Life-threatening features or poor respiratory effort","actions":["Activate resuscitation and critical-care support.","Arrange immediate transfer to a higher-acuity setting."]},{"condition":"Possible anaphylaxis","actions":["Follow local anaphylaxis protocol immediately.","Do not treat suspected anaphylaxis as asthma alone."]}]},{"id":"treat-reassess","title":"Treat and reassess","timeframe":"First hour and after each treatment cycle","actions":["Give indicated inhaled bronchodilator and other acute treatment per current MOH and local protocol.","Provide oxygen when indicated and titrate to local targets.","Repeat clinical and objective airflow assessment when safe."],"branches":[{"condition":"Inadequate response or deterioration","actions":["Escalate treatment and monitoring per local protocol.","Consult respiratory or critical-care specialists and arrange admission or transfer."]},{"condition":"Clear sustained improvement","actions":["Continue observation and reassessment.","Review controller therapy, inhaler technique, and action plan."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults and young people who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review. NG245 signposts retained BTS/SIGN acute-attack guidance and does not give a complete acute severe asthma drug/dose table on this page. Exact bronchodilator, oxygen and corticosteroid doses, contraindications and escalation thresholds require current acute-attack and Saudi/local protocol reconciliation. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"c7df45a8-8b34-4fcf-9689-fa5b7bade52c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults and young people who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Objective testing available during acute presentation","clinical_question":"Can asthma be objectively supported without delaying treatment?","expected_finding":"Eosinophil count, FeNO, spirometry or peak expiratory flow before and after bronchodilator may support diagnosis.","decision_rationale":"NICE recommends immediate treatment while performing available objective tests in acutely unwell or highly symptomatic people.","timeframe":"At presentation without delaying treatment"},{"test":"Deferred objective confirmation","clinical_question":"Were objective tests unreliable or unavailable during the attack?","expected_finding":"Testing after control may confirm asthma and reduce treatment-related false-normal results.","decision_rationale":"NICE advises completing objective testing after acute symptoms are controlled when it cannot be done immediately.","timeframe":"After acute symptoms are controlled"}],"evidence":{"sources":[{"id":"c7df45a8-8b34-4fcf-9689-fa5b7bade52c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults and young people who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Treat immediately when the person is acutely unwell or highly symptomatic; do not delay treatment for diagnostic testing.","timeframe":"Immediately"},{"instruction":"Review the personalised asthma action plan after an acute consultation, emergency attendance or hospital admission.","timeframe":"Before discharge or at the acute review"},{"instruction":"Review gaps: NG245 signposts retained BTS/SIGN acute-attack guidance and does not give a complete acute severe asthma drug/dose table on this page. Exact bronchodilator, oxygen and corticosteroid doses, contraindications and escalation thresholds require current acute-attack and Saudi/local protocol reconciliation.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"c7df45a8-8b34-4fcf-9689-fa5b7bade52c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults and young people who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."}}]},"nonClinicalManagement":{"patientEducation":["Review warning signs, written action plan, and inhaler technique."],"lifestyleAndDiet":["Discuss individualized trigger reduction and smoke avoidance.","Encourage prescribed controller adherence."],"mdtReferrals":["Respiratory/asthma service for severe or recurrent disease","Allergy service when relevant","Critical care for life-threatening exacerbation"],"dischargeCriteria":["Sustained improvement","Stable oxygenation and effort per local criteria","Patient understands regimen and return precautions","Follow-up documented"],"followUpPlan":"Arrange prompt primary-care or asthma-service review; earlier review if symptoms persist or recur."}}},{"id":"a1010000-0000-4000-8000-000000000001","title":"Acute Severe Asthma Exacerbation (Adult)","original_version_id":"a1010000-0000-4000-8000-000000000001","expected_hash":"623d61a926f3be62236d6658e408a463","source_url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","source_title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","scope":"Adults who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review.","content":{"id":"a1010000-0000-4000-8000-000000000001","title":"Acute Severe Asthma Exacerbation (Adult)","specialty":"Emergency Medicine and Respiratory Medicine","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2018-01-01","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"An acute exacerbation is a sustained worsening of airflow obstruction caused by bronchial smooth-muscle constriction, airway-wall oedema and mucus plugging on a background of variable airway inflammation. Severe obstruction raises the work of breathing, produces ventilation-perfusion mismatch and may progress from hypocapnia to carbon-dioxide retention as respiratory muscles fatigue.","keyMechanisms":["Trigger-driven airway inflammation and bronchial hyper-responsiveness narrow conducting airways.","Mucosal oedema and tenacious secretions amplify expiratory flow limitation and dynamic hyperinflation.","Ventilation-perfusion mismatch causes hypoxaemia; a normalising or rising carbon dioxide level in a distressed patient can indicate fatigue.","Prolonged expiration and air trapping increase intrathoracic pressure and the work of breathing."]},"presentation":{"symptoms":["Rapidly worsening breathlessness","Wheeze or chest tightness","Cough, often after a viral, allergen or irritant exposure","Reduced response to the patient's usual reliever medicine"],"physicalSigns":["Tachypnoea with prolonged expiration","Diffuse expiratory wheeze or, in near-fatal obstruction, a quiet chest","Accessory-muscle use and inability to complete sentences","Tachycardia with reduced peak expiratory flow compared with predicted or personal best"],"redFlags":["Exhaustion, confusion, drowsiness, cyanosis, hypotension or a silent chest","Inability to speak, worsening hypoxaemia or poor respiratory effort despite initial treatment","Normal or rising arterial carbon dioxide in a patient with severe respiratory distress","Previous near-fatal asthma, intensive-care admission or mechanical ventilation"]},"differentials":[{"condition":"Anaphylaxis","distinguishingFeatures":"Abrupt multisystem illness with urticaria, angioedema, hypotension or gastrointestinal symptoms after a likely exposure."},{"condition":"Acute pulmonary oedema","distinguishingFeatures":"Orthopnoea, inspiratory crackles, raised jugular venous pressure or radiographic congestion rather than predominantly expiratory obstruction."},{"condition":"Pulmonary embolism","distinguishingFeatures":"Pleuritic pain, haemoptysis, venous-thromboembolism risk factors or unexplained hypoxaemia with limited wheeze."},{"condition":"Pneumothorax","distinguishingFeatures":"Sudden unilateral pleuritic pain, asymmetric breath sounds and hyper-resonance; tension physiology adds hypotension and tracheal deviation."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Peak expiratory flow","modalityTarget":"Peak expiratory flow — Severity of airflow obstruction","targetCondition":"Severity of airflow obstruction","expectedFinding":"Marked reduction from predicted or documented personal best, with serial improvement after treatment supporting reversible obstruction.","clinicalRationale":"Provides an objective trend when the patient can perform the manoeuvre safely."},{"tier":"laboratory","testName":"Continuous pulse oximetry","modalityTarget":"Continuous pulse oximetry — Hypoxaemia","targetCondition":"Hypoxaemia","expectedFinding":"Reduced oxygen saturation or a need for supplemental oxygen to maintain the locally defined target.","clinicalRationale":"Detects gas-exchange impairment and guides titrated oxygen while avoiding delay to treatment."},{"tier":"laboratory","testName":"Arterial or venous blood gas when severe or deteriorating","modalityTarget":"Arterial or venous blood gas when severe or deteriorating — Respiratory failure and metabolic disturbance","targetCondition":"Respiratory failure and metabolic disturbance","expectedFinding":"Hypoxaemia; carbon-dioxide retention or acidaemia in life-threatening disease.","clinicalRationale":"A rising carbon dioxide level can signal fatigue and the need for critical-care escalation."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Chest radiograph when clinically indicated","modalityTarget":"Chest radiograph when clinically indicated — Pneumothorax, pneumonia or pulmonary oedema","targetCondition":"Pneumothorax, pneumonia or pulmonary oedema","expectedFinding":"No focal alternative pathology in uncomplicated asthma; an abnormality redirects management.","clinicalRationale":"Imaging is selective rather than routine and should not delay immediate bronchodilator treatment."},{"tier":"specializedAdjunctive","testName":"12-lead electrocardiogram","modalityTarget":"12-lead electrocardiogram — Acute coronary syndrome or significant arrhythmia","targetCondition":"Acute coronary syndrome or significant arrhythmia","expectedFinding":"Absence of acute ischaemic change or a clinically important rhythm disturbance.","clinicalRationale":"Useful for older patients, chest pain, marked tachycardia or relevant cardiovascular comorbidity."}]},"clinicalManagement":[{"id":"stabilise","title":"Immediate assessment and stabilisation","timeframe":"Immediately on arrival","actions":["Use an airway-breathing-circulation approach and call senior emergency support for severe or life-threatening features.","Position upright when tolerated, establish monitoring and obtain intravenous access without delaying inhaled therapy.","Give controlled oxygen to the locally approved saturation target and reassess frequently."]},{"id":"bronchodilate","title":"Reverse bronchoconstriction","timeframe":"Within minutes","actions":["Give repeated inhaled short-acting beta-2 agonist using an appropriate delivery system.","Add inhaled ipratropium bromide in severe or life-threatening exacerbation.","Document response using symptoms, respiratory effort, oxygenation and peak flow where feasible."],"branches":[{"condition":"Poor response or deteriorating physiology","actions":["Escalate immediately to a senior emergency/critical-care clinician.","Consider continuous nebulised bronchodilator delivery and intravenous magnesium sulfate under the approved local protocol."]}]},{"id":"anti-inflammatory","title":"Treat airway inflammation","timeframe":"Early in the first hour","actions":["Administer systemic corticosteroid promptly unless contraindicated.","Review likely trigger, adherence and recent corticosteroid exposure.","Do not use antibiotics routinely unless bacterial infection is clinically supported."]},{"id":"reassess","title":"Structured reassessment","timeframe":"After each initial treatment cycle","actions":["Repeat respiratory rate, work of breathing, speech, oxygen saturation and peak flow where possible.","Check for complications and alternative diagnoses if the trajectory is not improving.","Escalate for ventilatory support planning before exhaustion or reduced consciousness develops."]},{"id":"disposition","title":"Determine safe disposition","timeframe":"After sustained clinical response","actions":["Admit patients with persistent severe features, oxygen requirement, poor social support or high relapse risk.","Before discharge, verify inhaler technique, provide an individualised written action plan and arrange controller therapy review.","Explain explicit emergency return precautions."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review. NG245 signposts retained BTS/SIGN acute-attack guidance and does not give a complete acute severe asthma drug/dose table on this page. Exact bronchodilator, oxygen and corticosteroid doses, contraindications and escalation thresholds require current acute-attack and Saudi/local protocol reconciliation. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"f29ba80b-af70-4869-9442-ce4eea41210c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Objective testing available during acute presentation","clinical_question":"Can asthma be objectively supported without delaying treatment?","expected_finding":"Eosinophil count, FeNO, spirometry or peak expiratory flow before and after bronchodilator may support diagnosis.","decision_rationale":"NICE recommends immediate treatment while performing available objective tests in acutely unwell or highly symptomatic people.","timeframe":"At presentation without delaying treatment"},{"test":"Deferred objective confirmation","clinical_question":"Were objective tests unreliable or unavailable during the attack?","expected_finding":"Testing after control may confirm asthma and reduce treatment-related false-normal results.","decision_rationale":"NICE advises completing objective testing after acute symptoms are controlled when it cannot be done immediately.","timeframe":"After acute symptoms are controlled"}],"evidence":{"sources":[{"id":"f29ba80b-af70-4869-9442-ce4eea41210c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Treat immediately when the adult is acutely unwell or highly symptomatic; do not delay treatment for diagnostic testing.","timeframe":"Immediately"},{"instruction":"Review the personalised asthma action plan after an acute consultation, emergency attendance or hospital admission.","timeframe":"Before discharge or at the acute review"},{"instruction":"Review gaps: NG245 signposts retained BTS/SIGN acute-attack guidance and does not give a complete acute severe asthma drug/dose table on this page. Exact bronchodilator, oxygen and corticosteroid doses, contraindications and escalation thresholds require current acute-attack and Saudi/local protocol reconciliation.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"f29ba80b-af70-4869-9442-ce4eea41210c","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7 and 1.14.2","primary_source":true}],"selection_rationale":"Unverified scope: Adults who are acutely unwell or highly symptomatic at presentation; limited to immediate treatment, objective testing and post-attack action-plan review."}}]},"nonClinicalManagement":{"patientEducation":["Explain reliever versus controller medicines and the danger of relying on frequent reliever use.","Demonstrate inhaler and spacer technique and confirm understanding using teach-back.","Provide a written action plan that states deterioration thresholds and where to obtain urgent care."],"lifestyleAndDiet":["Identify and reduce exposure to tobacco smoke, vaping, occupational irritants and known allergens.","Support influenza vaccination and other indicated immunisation under the Saudi schedule.","Encourage gradual return to activity once symptoms and peak flow recover."],"mdtReferrals":["Respiratory specialist for life-threatening, recurrent severe or diagnostically uncertain asthma","Asthma educator or respiratory pharmacist for technique and adherence review","Critical care when deterioration, exhaustion or ventilatory support is anticipated"],"dischargeCriteria":["Symptoms and work of breathing have improved and remain stable after observation.","Oxygenation is stable without unplanned escalation and objective airflow is improving.","Medicines, inhaler technique, written action plan, follow-up and return precautions are confirmed."],"followUpPlan":"Arrange prompt primary-care or respiratory review after discharge, with earlier assessment for recurrent symptoms; review the trigger, control, adherence, inhaler technique and need to step up long-term therapy."}}},{"id":"6fccc942-c6f3-4ef7-94cf-26fd23edfd27","title":"Acute Upper Gastrointestinal Bleeding","original_version_id":"6fccc942-c6f3-4ef7-94cf-26fd23edfd27","expected_hash":"985bd0ee33155714b9f0723cb8bd8748","source_url":"https://www.nice.org.uk/guidance/cg141/chapter/recommendations","source_title":"Acute upper gastrointestinal bleeding in over 16s: management","issuer":"NICE","scope":"People aged over 16 with acute upper gastrointestinal bleeding; limited to risk assessment, resuscitation-linked endoscopy timing and selected named treatments.","content":{"id":"6fccc942-c6f3-4ef7-94cf-26fd23edfd27","title":"Acute Upper Gastrointestinal Bleeding","specialty":"Gastroenterology / Emergency Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Bleeding proximal to the ligament of Treitz can arise from ulceration, varices, erosions, malignancy, or vascular lesions. Blood loss may progress rapidly; liver disease and antithrombotic medicines change the risk and management pathway. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Bleeding proximal to the ligament of Treitz can arise from ulceration, varices, erosions, malignancy, or vascular lesions. Blood loss may progress rapidly","liver disease and antithrombotic medicines change the risk and management pathway."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Acute Upper Gastrointestinal Bleeding, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Shock or ongoing brisk haematemesis","Syncope with instability or altered mental state","Suspected variceal bleeding","Airway compromise or major comorbidity"]},"differentials":[{"condition":"Lower GI source","distinguishingFeatures":"Brisk upper bleeding can present with red blood; source needs evaluation."},{"condition":"Swallowed nasal/oral blood","distinguishingFeatures":"Examine for an alternative source when history suggests it."},{"condition":"Aortoenteric fistula","distinguishingFeatures":"Prior aortic graft with GI bleeding is a time-critical emergency."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"CBC, renal profile, coagulation, liver tests, ECG when appropriate, and type/crossmatch.","modalityTarget":"CBC, renal profile, coagulation, liver tests, ECG when appropriate, and type/crossmatch. — Acute Upper Gastrointestinal Bleeding","targetCondition":"Acute Upper Gastrointestinal Bleeding","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"specializedAdjunctive","testName":"Endoscopy timing and risk stratification follow current local protocol after stabilisation.","modalityTarget":"Endoscopy timing and risk stratification follow current local protocol after stabilisation. — Cause, complication, or risk relevant to Acute Upper Gastrointestinal Bleeding","targetCondition":"Cause, complication, or risk relevant to Acute Upper Gastrointestinal Bleeding","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Acute Upper Gastrointestinal Bleeding","targetCondition":"Important alternative to Acute Upper Gastrointestinal Bleeding","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People aged over 16 with acute upper gastrointestinal bleeding; limited to risk assessment, resuscitation-linked endoscopy timing and selected named treatments. The recommendation page names prothrombin complex concentrate, proton pump inhibitors and terlipressin but does not provide complete dose, route, frequency, duration or contraindication data. Local massive-haemorrhage, anticoagulant-reversal, variceal-bleed and formulary protocols are required before approval. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"aed7ea7d-d34f-42b9-860d-13d4b350b4ef","title":"Acute upper gastrointestinal bleeding in over 16s: management","issuer":"NICE","edition":"CG141, recommendations page updated March 2025","url":"https://www.nice.org.uk/guidance/cg141/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.2, 1.2.5 to 1.2.8, 1.3.1 to 1.5.1","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with acute upper gastrointestinal bleeding; limited to risk assessment, resuscitation-linked endoscopy timing and selected named treatments."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Blatchford score","clinical_question":"What is the pre-endoscopy risk and is early discharge potentially appropriate?","expected_finding":"A score of 0 identifies people for whom early discharge may be considered.","decision_rationale":"NICE recommends the Blatchford score at first assessment.","timeframe":"At first assessment"},{"test":"Upper gastrointestinal endoscopy","clinical_question":"What is the bleeding source and is endoscopic haemostasis required?","expected_finding":"Endoscopy identifies variceal or non-variceal bleeding and stigmata of recent haemorrhage.","decision_rationale":"NICE recommends immediate endoscopy after resuscitation for unstable severe bleeding and within 24 hours for other patients.","timeframe":"Immediately after resuscitation if unstable; otherwise within 24 hours of admission"}],"evidence":{"sources":[{"id":"aed7ea7d-d34f-42b9-860d-13d4b350b4ef","title":"Acute upper gastrointestinal bleeding in over 16s: management","issuer":"NICE","edition":"CG141, recommendations page updated March 2025","url":"https://www.nice.org.uk/guidance/cg141/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.2, 1.2.5 to 1.2.8, 1.3.1 to 1.5.1","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with acute upper gastrointestinal bleeding; limited to risk assessment, resuscitation-linked endoscopy timing and selected named treatments."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer endoscopy to unstable patients with severe bleeding immediately after resuscitation; offer it within 24 hours to all other patients.","timeframe":"After initial resuscitation"},{"instruction":"For non-variceal bleeding, do not use adrenaline alone; use a recommended mechanical, thermal, fibrin or thrombin method with or without adrenaline as specified by NICE.","timeframe":"During therapeutic endoscopy"},{"instruction":"Offer terlipressin at presentation when variceal bleeding is suspected, then stop after definitive haemostasis or after 5 days unless another indication exists.","timeframe":"At presentation through definitive haemostasis, maximum 5 days per the recommendation"},{"instruction":"Review gaps: The recommendation page names prothrombin complex concentrate, proton pump inhibitors and terlipressin but does not provide complete dose, route, frequency, duration or contraindication data. Local massive-haemorrhage, anticoagulant-reversal, variceal-bleed and formulary protocols are required before approval.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"aed7ea7d-d34f-42b9-860d-13d4b350b4ef","title":"Acute upper gastrointestinal bleeding in over 16s: management","issuer":"NICE","edition":"CG141, recommendations page updated March 2025","url":"https://www.nice.org.uk/guidance/cg141/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.2, 1.2.5 to 1.2.8, 1.3.1 to 1.5.1","primary_source":true}],"selection_rationale":"Unverified scope: People aged over 16 with acute upper gastrointestinal bleeding; limited to risk assessment, resuscitation-linked endoscopy timing and selected named treatments."}}]},"nonClinicalManagement":{"patientEducation":["Explain acute upper gastrointestinal bleeding in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Gastroenterology / Emergency Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"c36e9014-7d53-4a82-b641-8e05a3c9d627","title":"Adult Essential Hypertension Screening and Confirmation","original_version_id":"c36e9014-7d53-4a82-b641-8e05a3c9d627","expected_hash":"2dc406ff776c7d23718c4827c0a0e219","source_url":"https://www.nice.org.uk/guidance/ng136/chapter/recommendations","source_title":"Hypertension in adults: diagnosis and management","issuer":"NICE","scope":"Adults undergoing blood-pressure measurement, confirmation of hypertension and target-organ-damage assessment.","content":{"id":"c36e9014-7d53-4a82-b641-8e05a3c9d627","title":"Adult Essential Hypertension Screening and Confirmation","specialty":"Primary Care and Family Medicine","authority":"MOH","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Essential hypertension is persistently elevated arterial blood pressure without an identified secondary cause. It is often asymptomatic and increases cardiovascular, cerebrovascular, and kidney risk.","keyMechanisms":["Interactions among genetic, renal, vascular, neurohormonal, and environmental factors","Increased systemic vascular resistance and altered sodium-volume regulation","Cumulative pressure-related vascular and target-organ injury"]},"presentation":{"symptoms":["Usually asymptomatic","Occasional non-specific headache or dizziness, which cannot establish diagnosis"],"physicalSigns":["Elevated pressure on correctly performed measurement","Possible target-organ disease in established hypertension","Possible clinical clues to a secondary cause"],"redFlags":["Severe elevation with chest pain, dyspnoea, neurological deficit, confusion, visual loss, or acute kidney injury","Pregnancy with elevated pressure or pre-eclampsia symptoms","Abrupt onset, resistant readings, or suspected secondary cause"]},"differentials":[{"condition":"White-coat hypertension","distinguishingFeatures":"Clinic readings elevated but validated out-of-office average not persistently elevated."},{"condition":"Masked hypertension","distinguishingFeatures":"Clinic readings may be below threshold while home or ambulatory readings are elevated."},{"condition":"Secondary hypertension","distinguishingFeatures":"Young onset, abrupt worsening, resistance, relevant medicines, renal or endocrine clues."},{"condition":"Transient elevation","distinguishingFeatures":"Pain, anxiety, acute illness, stimulants, or measurement error; repeat under standardised conditions."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Repeated standardised clinic blood-pressure measurement","modalityTarget":"Repeated standardised clinic blood-pressure measurement — Persistently elevated blood pressure","targetCondition":"Persistently elevated blood pressure","expectedFinding":"Repeated readings meeting locally adopted threshold using validated device and correct cuff","clinicalRationale":"Reduce misclassification from poor technique or transient elevation."},{"tier":"specializedAdjunctive","testName":"Home or ambulatory blood-pressure monitoring","modalityTarget":"Home or ambulatory blood-pressure monitoring — Sustained hypertension","targetCondition":"Sustained hypertension","expectedFinding":"Out-of-office average meeting locally adopted threshold","clinicalRationale":"Confirm persistence and identify white-coat or masked hypertension."},{"tier":"laboratory","testName":"Creatinine, estimated glomerular filtration rate, electrolytes, urine albumin, and urinalysis","modalityTarget":"Creatinine, estimated glomerular filtration rate, electrolytes, urine albumin, and urinalysis — Target-organ involvement or possible secondary hypertension","targetCondition":"Target-organ involvement or possible secondary hypertension","expectedFinding":"Renal impairment, albuminuria, electrolyte abnormality, or other finding needing assessment","clinicalRationale":"Assess baseline kidney health and direct further evaluation."},{"tier":"specializedAdjunctive","testName":"Electrocardiogram","modalityTarget":"Electrocardiogram — Cardiac target-organ involvement","targetCondition":"Cardiac target-organ involvement","expectedFinding":"Possible left ventricular hypertrophy, rhythm abnormality, or prior cardiac disease","clinicalRationale":"Assess cardiovascular context; normal ECG does not exclude hypertension."}],"ruleOut":[{"tier":"laboratory","testName":"Repeat standardised readings after rest","modalityTarget":"Repeat standardised readings after rest — Transient or measurement-related elevation","targetCondition":"Transient or measurement-related elevation","expectedFinding":"Repeat readings below locally adopted threshold","clinicalRationale":"Check for technique-related or transient elevation."},{"tier":"specializedAdjunctive","testName":"Validated home or ambulatory monitoring","modalityTarget":"Validated home or ambulatory monitoring — White-coat hypertension","targetCondition":"White-coat hypertension","expectedFinding":"Out-of-office average below local threshold despite elevated clinic readings","clinicalRationale":"Avoid relying on clinic readings alone when results are discordant."},{"tier":"laboratory","testName":"Targeted secondary-hypertension investigations","modalityTarget":"Targeted secondary-hypertension investigations — Secondary cause of elevated blood pressure","targetCondition":"Secondary cause of elevated blood pressure","expectedFinding":"No targeted evidence for the suspected cause","clinicalRationale":"Select testing using clinical indications rather than broad routine testing."}]},"clinicalManagement":[{"id":"htn-1","title":"Screen and measure accurately","timeframe":"Preventive and primary-care encounters, or when indicated","actions":["Use a validated device, correct cuff, and standardised seated measurement after rest.","Obtain repeat readings and document method, values, symptoms, and context.","Review medicines, supplements, stimulants, tobacco, pain, and acute illness.","Do not diagnose from one isolated value unless urgent circumstances require action."],"branches":[{"condition":"Elevated screening measurement without acute symptoms","actions":["Arrange repeat and out-of-office confirmation within a risk-appropriate interval.","Explain follow-up and symptoms needing urgent assessment."]},{"condition":"Severe elevation with possible acute target-organ injury","actions":["Arrange immediate emergency assessment.","Avoid rapid unsupervised outpatient lowering."]}]},{"id":"htn-2","title":"Confirm diagnosis and assess risk","timeframe":"After elevated screening readings","actions":["Confirm sustained hypertension with repeated clinic and/or validated out-of-office readings.","Assess cardiovascular risk, kidney function, diabetes, lipids, smoking, and target-organ injury.","Investigate secondary causes when clinical indications are present.","Agree an individualised plan and follow-up interval."],"branches":[{"condition":"Out-of-office values are not persistently elevated","actions":["Consider white-coat hypertension rather than labelling sustained disease.","Continue monitoring based on overall risk."]},{"condition":"Secondary cause or target-organ injury suspected","actions":["Arrange targeted work-up and specialist input as appropriate.","Address urgent complications through emergency care."]}]},{"id":"htn-3","title":"Reduce risk and provide ongoing care","timeframe":"After diagnosis and at regular follow-up","actions":["Offer lifestyle measures and treatment options under current local guidance.","Select medication when indicated based on comorbidities, renal function, pregnancy potential, contraindications, and preference.","Review pressure, adherence, adverse effects, renal function, and risk after treatment changes.","Escalate persistent uncontrolled readings or suspected complications."],"branches":[{"condition":"Pregnancy or pregnancy potential","actions":["Use a pregnancy-specific assessment and treatment pathway.","Review medicines promptly and involve obstetric care when indicated."]},{"condition":"Pressure remains above agreed target","actions":["Confirm measurement technique and adherence; review interfering medicines and secondary causes.","Adjust treatment or refer under local guidance."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults undergoing blood-pressure measurement, confirmation of hypertension and target-organ-damage assessment. This extraction does not select a specific antihypertensive product or dose. Pregnancy, chronic kidney disease, type 1 diabetes, frailty, resistant hypertension and Saudi/local thresholds require dedicated reconciliation before approval. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"d9172498-65f8-4c96-bf9a-b457238729ed","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, last updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3 and 1.4.19 to 1.4.24","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing blood-pressure measurement, confirmation of hypertension and target-organ-damage assessment."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Standardised clinic blood pressure in both arms","clinical_question":"Is clinic blood pressure raised and is there a persistent inter-arm difference?","expected_finding":"Clinic blood pressure of 140/90 mmHg or higher prompts repeat measurement and confirmation; a persistent inter-arm difference over 15 mmHg directs future measurements to the higher arm.","decision_rationale":"NICE specifies standardised technique, repeat measurement and bilateral assessment.","timeframe":"At initial assessment"},{"test":"Ambulatory or home blood pressure monitoring","clinical_question":"Is hypertension confirmed outside the clinic?","expected_finding":"A daytime ABPM or HBPM average of 135/85 mmHg or higher with clinic pressure at least 140/90 mmHg confirms hypertension.","decision_rationale":"NICE recommends ABPM, or HBPM when ABPM is unsuitable, for confirmation below severe-hypertension thresholds.","timeframe":"After raised clinic blood pressure is identified"},{"test":"Target-organ-damage assessment","clinical_question":"Is there renal, metabolic, retinal or cardiac involvement?","expected_finding":"Urine ACR and haematuria testing, HbA1c, electrolytes, creatinine/eGFR, cholesterol, fundoscopy and 12-lead ECG identify associated risk or damage.","decision_rationale":"NICE recommends this assessment for all people with hypertension.","timeframe":"During diagnostic assessment"}],"evidence":{"sources":[{"id":"d9172498-65f8-4c96-bf9a-b457238729ed","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, last updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3 and 1.4.19 to 1.4.24","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing blood-pressure measurement, confirmation of hypertension and target-organ-damage assessment."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer lifestyle advice to people with suspected or diagnosed hypertension and repeat it periodically.","timeframe":"From initial assessment and at review"},{"instruction":"Provide annual review for adults with hypertension to monitor blood pressure and discuss lifestyle, symptoms and medication.","timeframe":"At least annually"},{"instruction":"Review gaps: This extraction does not select a specific antihypertensive product or dose. Pregnancy, chronic kidney disease, type 1 diabetes, frailty, resistant hypertension and Saudi/local thresholds require dedicated reconciliation before approval.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"d9172498-65f8-4c96-bf9a-b457238729ed","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, last updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3 and 1.4.19 to 1.4.24","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing blood-pressure measurement, confirmation of hypertension and target-organ-damage assessment."}}]},"nonClinicalManagement":{"patientEducation":["Explain that hypertension is often symptom-free and needs accurate measurement and follow-up.","Teach home-monitoring technique when used.","Explain urgent symptoms requiring immediate assessment."],"lifestyleAndDiet":["Discuss balanced eating and sodium reduction where appropriate.","Encourage regular activity, healthy weight goals, and tobacco cessation.","Discuss alcohol use consistent with health needs and local advice."],"mdtReferrals":["Primary care or family medicine","Dietitian or lifestyle support","Cardiology, nephrology, or endocrinology when indicated","Obstetrics for pregnancy-associated hypertension"],"dischargeCriteria":["Measurement result, confirmation plan, and precautions are documented.","Acute target-organ injury is assessed and disposition determined.","Patient knows when blood pressure will be reassessed."],"followUpPlan":"Arrange repeat clinic or out-of-office measurements and cardiovascular-risk review according to results, patient risk, and local guidance."}}},{"id":"a1010000-0000-4000-8000-000000000008","title":"Adult Periodic Health Examination","original_version_id":"a1010000-0000-4000-8000-000000000008","expected_hash":"39137b113493bd019ea23cbfcaff5dad","source_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation-topics/uspstf-a-and-b-recommendations","source_title":"US Preventive Services Task Force A and B Recommendations","issuer":"Other","scope":"Asymptomatic adults considered for preventive services; each service remains conditional on the population, age, sex, pregnancy and risk criteria stated in its linked recommendation.","content":{"id":"a1010000-0000-4000-8000-000000000008","title":"Adult Periodic Health Examination","specialty":"Family Medicine and Preventive Medicine","authority":"PHA","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2023-01-01","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Periodic health examination is a risk-based preventive-care process rather than a disease episode. It identifies modifiable cardiovascular, metabolic, cancer, infectious, mental-health and functional risks before symptoms or irreversible complications develop, while avoiding screening that has an unfavourable balance of benefit and harm.","keyMechanisms":["Age, sex, family history, exposures and comorbidity alter baseline disease probability and screening benefit.","Repeated measurement can detect trajectories in blood pressure, adiposity, glycaemia and lipids before complications emerge.","Evidence-based screening shifts selected cancers and chronic diseases toward earlier diagnosis.","Shared decisions reduce harms from false positives, overdiagnosis and preventive medicines with small net benefit."]},"presentation":{"symptoms":["Often asymptomatic attendance for preventive review","May disclose fatigue, low mood, sleep problems or reduced function during structured history","May report tobacco exposure, inactivity, unhealthy diet or occupational risk","May have overdue vaccination or cancer screening"],"physicalSigns":["Elevated or discrepant blood-pressure readings","Raised body-mass index or waist circumference","Oral-health, vision, hearing or mobility concerns","Abnormal findings requiring conversion from screening to a diagnostic pathway"],"redFlags":["Chest pain, focal neurological deficit, severe breathlessness or syncope discovered during screening","Markedly elevated blood pressure with acute target-organ symptoms","Suicidal ideation or immediate safeguarding concern","Alarm cancer symptoms such as unexplained bleeding, persistent mass or major unintentional weight loss"]},"differentials":[{"condition":"Routine preventive need","distinguishingFeatures":"Asymptomatic, eligible by age or risk and suitable for a validated screening intervention."},{"condition":"Established disease requiring chronic-care review","distinguishingFeatures":"Known diagnosis or repeated abnormal result requiring disease-specific targets rather than screening thresholds."},{"condition":"Symptomatic undiagnosed disease","distinguishingFeatures":"Symptoms or signs raise pre-test probability and require diagnostic, not screening, tests."},{"condition":"Transient measurement abnormality","distinguishingFeatures":"Single clinic value is not confirmed on repeat or out-of-office measurement."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Standardised blood-pressure measurement with out-of-office confirmation","modalityTarget":"Standardised blood-pressure measurement with out-of-office confirmation — Hypertension","targetCondition":"Hypertension","expectedFinding":"Persistently elevated readings confirmed outside the clinic when indicated.","clinicalRationale":"Reduces misclassification from technique, white-coat effect and isolated readings."},{"tier":"laboratory","testName":"Risk-based glucose testing","modalityTarget":"Risk-based glucose testing — Prediabetes or diabetes","targetCondition":"Prediabetes or diabetes","expectedFinding":"Abnormal fasting glucose, random glucose in context or glycated haemoglobin confirmed through the diagnostic pathway.","clinicalRationale":"PHA guidance begins routine adult testing at the defined age and earlier with overweight plus risk factors."},{"tier":"laboratory","testName":"Age-, sex- and risk-appropriate cancer screening","modalityTarget":"Age-, sex- and risk-appropriate cancer screening — Preclinical breast, colorectal, cervical or lung cancer","targetCondition":"Preclinical breast, colorectal, cervical or lung cancer","expectedFinding":"Negative screening at the recommended interval or an abnormal result requiring timely diagnostic confirmation.","clinicalRationale":"Benefit depends on eligibility, interval and complete follow-through after an abnormal screen."}],"ruleOut":[{"tier":"laboratory","testName":"Repeat or confirmatory diagnostic test after an abnormal screen","modalityTarget":"Repeat or confirmatory diagnostic test after an abnormal screen — False-positive screening result","targetCondition":"False-positive screening result","expectedFinding":"Diagnostic testing does not confirm disease.","clinicalRationale":"Screening tests do not by themselves establish many diagnoses."},{"tier":"laboratory","testName":"Medication and comorbidity review","modalityTarget":"Medication and comorbidity review — Secondary or iatrogenic risk","targetCondition":"Secondary or iatrogenic risk","expectedFinding":"A medicine, pregnancy state, renal disease or other condition explains or changes the preventive finding.","clinicalRationale":"Prevents inappropriate application of general-population screening or treatment advice."}]},"clinicalManagement":[{"id":"risk-inventory","title":"Build an individual risk inventory","timeframe":"At each periodic examination","actions":["Record age, sex, pregnancy potential, family history, tobacco exposure, occupation, medicines, comorbidity and prior screening.","Assess mental health, safety, function and social determinants with validated tools where appropriate.","Separate asymptomatic screening from symptoms that require diagnostic evaluation."]},{"id":"measure","title":"Complete core measurements","timeframe":"During the visit","actions":["Measure blood pressure using validated technique and assess body-mass index and waist circumference at the PHA interval.","Order glucose and lipid testing according to age and risk.","Review oral health, vaccination status and age-related vision, hearing, falls or cognition needs."]},{"id":"screen","title":"Offer eligible screening","timeframe":"At the guideline-defined interval","actions":["Offer breast, cervical, colorectal, lung, osteoporosis and abdominal-aortic-aneurysm screening only when age, sex and risk criteria are met.","Explain likely benefits, limitations and follow-up before testing.","Create a closed-loop plan for every abnormal result."]},{"id":"prevent","title":"Deliver preventive interventions","timeframe":"At the same visit or scheduled follow-up","actions":["Provide indicated immunisation under the current Saudi schedule.","Offer tobacco-cessation treatment, physical-activity and dietary support.","Use generic preventive pharmacotherapy only after formal cardiovascular-risk, contraindication and shared-decision assessment."]},{"id":"close-loop","title":"Close the preventive-care loop","timeframe":"After results are available","actions":["Communicate normal and abnormal results in understandable language.","Convert confirmed abnormalities to the relevant diagnostic or chronic-care pathway.","Update the recall date and assign ownership for referrals and pending tests."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Asymptomatic adults considered for preventive services; each service remains conditional on the population, age, sex, pregnancy and risk criteria stated in its linked recommendation. This index is not a Saudi periodic-health-examination schedule and does not replace service-specific recommendation statements. Every proposed screen needs current Saudi eligibility, interval, test method, harms and referral-pathway reconciliation; no medicine regimen is supported by this extraction. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"ec6e54c2-ea08-4fc3-b872-180208fc83ea","title":"US Preventive Services Task Force A and B Recommendations","issuer":"Other","edition":"Current recommendations page retrieved 11 October 2026","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation-topics/uspstf-a-and-b-recommendations","locator":"A and B Recommendations table; eligibility and recommendation-date columns","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic adults considered for preventive services; each service remains conditional on the population, age, sex, pregnancy and risk criteria stated in its linked recommendation."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Age-, sex-, pregnancy- and risk-based preventive eligibility review","clinical_question":"Which current USPSTF grade A or B services apply to this individual?","expected_finding":"Only services whose linked population criteria match the individual should be offered or discussed.","decision_rationale":"The source is an index of preventive services with moderate or substantial net benefit for defined populations.","timeframe":"At each periodic preventive review"}],"evidence":{"sources":[{"id":"ec6e54c2-ea08-4fc3-b872-180208fc83ea","title":"US Preventive Services Task Force A and B Recommendations","issuer":"Other","edition":"Current recommendations page retrieved 11 October 2026","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation-topics/uspstf-a-and-b-recommendations","locator":"A and B Recommendations table; eligibility and recommendation-date columns","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic adults considered for preventive services; each service remains conditional on the population, age, sex, pregnancy and risk criteria stated in its linked recommendation."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Open the current service-specific recommendation before ordering a screen and document that its population and risk criteria apply.","timeframe":"During the periodic examination"},{"instruction":"Reconcile selected services with current Saudi Ministry of Health programmes and local referral capacity.","timeframe":"Before clinical use or approval"},{"instruction":"Review gaps: This index is not a Saudi periodic-health-examination schedule and does not replace service-specific recommendation statements. Every proposed screen needs current Saudi eligibility, interval, test method, harms and referral-pathway reconciliation; no medicine regimen is supported by this extraction.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"ec6e54c2-ea08-4fc3-b872-180208fc83ea","title":"US Preventive Services Task Force A and B Recommendations","issuer":"Other","edition":"Current recommendations page retrieved 11 October 2026","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation-topics/uspstf-a-and-b-recommendations","locator":"A and B Recommendations table; eligibility and recommendation-date columns","primary_source":true}],"selection_rationale":"Unverified scope: Asymptomatic adults considered for preventive services; each service remains conditional on the population, age, sex, pregnancy and risk criteria stated in its linked recommendation."}}]},"nonClinicalManagement":{"patientEducation":["Explain that preventive tests are selected by personal risk and that more testing is not always safer.","Use shared decision making for preference-sensitive cancer screening and preventive medicines.","Give accessible instructions for preparation, result access and the next step after an abnormal result."],"lifestyleAndDiet":["Support a sustainable dietary pattern rich in vegetables, fruit, whole grains and minimally processed foods while accounting for culture and comorbidity.","Encourage regular aerobic and strengthening activity adapted to ability.","Provide tobacco cessation, sleep, weight and oral-health support without stigma."],"mdtReferrals":["Primary-care nurse or preventive-care coordinator for recall and result tracking","Dietitian, tobacco-cessation service or exercise professional according to risk","Mental-health service for confirmed depression, anxiety or safety concern","Diagnostic specialty pathway for any abnormal screening result"],"dischargeCriteria":["Risk profile, due interventions and deferred shared decisions are documented.","Every test and referral has a named owner and result-communication method.","Urgent symptoms or severe abnormalities have been diverted to immediate assessment."],"followUpPlan":"Maintain a personalised recall schedule based on the 2023 PHA age and risk tables, review abnormal results promptly, and update eligibility whenever health status, family history, pregnancy status or exposure changes."}}},{"id":"1dd5fa99-fc60-44e6-94f4-6de6287a1244","title":"Adult Vaccination Review","original_version_id":"1dd5fa99-fc60-44e6-94f4-6de6287a1244","expected_hash":"75bb5e370792fa98dcc5ed0a4d59bf7c","source_url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/downloads/adult/adult-combined-schedule-bw.pdf","source_title":"CDC Recommended Adult Immunization Schedule for Ages 19 Years or Older","issuer":"Other","scope":"Adults aged 19 years or older reviewed by age, vaccination history, medical condition and other indication using the current CDC-hosted schedule.","content":{"id":"1dd5fa99-fc60-44e6-94f4-6de6287a1244","title":"Adult Vaccination Review","specialty":"Family Medicine / Public Health","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Vaccination reduces susceptible-host risk and community transmission through antigen-specific immune memory. Benefit and safety depend on age, comorbidity, immune status, prior doses, exposure, and current national recommendations. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Vaccination reduces susceptible-host risk and community transmission through antigen-specific immune memory. Benefit and safety depend on age, comorbidity, immune status, prior doses, exposure, and current national recommendations.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Adult Vaccination Review, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Severe allergic reaction history","Immunocompromise affecting live vaccines","Current acute illness or pregnancy influencing timing","Travel exposure with urgent prophylaxis window"]},"differentials":[{"condition":"Natural immunity or previous vaccination","distinguishingFeatures":"Use records and serology only where nationally recommended."},{"condition":"Vaccine adverse event","distinguishingFeatures":"Separate expected symptoms from contraindication-level reaction."},{"condition":"Unrecorded dose","distinguishingFeatures":"Check registry or prior provider before deciding repeat schedule."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Reconcile immunisation registry and records; review age, comorbidities, medicines, pregnancy, travel and occupational exposures.","modalityTarget":"Reconcile immunisation registry and records; review age, comorbidities, medicines, pregnancy, travel and occupational exposures. — Adult Vaccination Review","targetCondition":"Adult Vaccination Review","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Compare against current Saudi MOH/PHA schedule and product information; document plan and next due date.","modalityTarget":"Compare against current Saudi MOH/PHA schedule and product information; document plan and next due date. — Cause, complication, or risk relevant to Adult Vaccination Review","targetCondition":"Cause, complication, or risk relevant to Adult Vaccination Review","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Adult Vaccination Review","targetCondition":"Important alternative to Adult Vaccination Review","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults aged 19 years or older reviewed by age, vaccination history, medical condition and other indication using the current CDC-hosted schedule. This is a United States schedule and must be reconciled with the current Saudi national immunisation schedule, locally available products and product information. Product-specific dose volume, route, contraindications and special-population rules must be rechecked before prescribing or administration. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"4685fc57-8187-4dac-b385-908689fbcc10","title":"CDC Recommended Adult Immunization Schedule for Ages 19 Years or Older","issuer":"Other","edition":"United States, 2025 schedule currently displayed by CDC under court-order notice","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/downloads/adult/adult-combined-schedule-bw.pdf","locator":"Tables 1 and 2, Notes, and Appendix on contraindications and precautions","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 19 years or older reviewed by age, vaccination history, medical condition and other indication using the current CDC-hosted schedule."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Documented vaccine history and age review","clinical_question":"Which routine vaccine series are complete, due or missing?","expected_finding":"The age table and notes identify candidate routine and catch-up vaccines.","decision_rationale":"CDC directs clinicians to determine recommendations by age and then consult the notes.","timeframe":"At every adult vaccination review"},{"test":"Medical-condition and contraindication screen","clinical_question":"Do comorbidities create an indication, contraindication or precaution?","expected_finding":"The medical-condition table and appendix identify additional indications and safety restrictions.","decision_rationale":"CDC requires condition-based review and the contraindications/precautions appendix before administration.","timeframe":"Before each vaccine is administered"}],"evidence":{"sources":[{"id":"4685fc57-8187-4dac-b385-908689fbcc10","title":"CDC Recommended Adult Immunization Schedule for Ages 19 Years or Older","issuer":"Other","edition":"United States, 2025 schedule currently displayed by CDC under court-order notice","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/downloads/adult/adult-combined-schedule-bw.pdf","locator":"Tables 1 and 2, Notes, and Appendix on contraindications and precautions","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 19 years or older reviewed by age, vaccination history, medical condition and other indication using the current CDC-hosted schedule."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Determine recommended vaccines by age, then assess medical-condition indications, dosing intervals, special situations, contraindications and precautions in the linked notes and appendix.","timeframe":"During the vaccination review"},{"instruction":"Defer a vaccine when a listed precaution is present unless an individual benefit-risk assessment supports administration; do not administer when a listed contraindication is present.","timeframe":"Before administration"},{"instruction":"Review gaps: This is a United States schedule and must be reconciled with the current Saudi national immunisation schedule, locally available products and product information. Product-specific dose volume, route, contraindications and special-population rules must be rechecked before prescribing or administration.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"4685fc57-8187-4dac-b385-908689fbcc10","title":"CDC Recommended Adult Immunization Schedule for Ages 19 Years or Older","issuer":"Other","edition":"United States, 2025 schedule currently displayed by CDC under court-order notice","url":"https://www.cdc.gov/vaccines/hcp/imz-schedules/downloads/adult/adult-combined-schedule-bw.pdf","locator":"Tables 1 and 2, Notes, and Appendix on contraindications and precautions","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 19 years or older reviewed by age, vaccination history, medical condition and other indication using the current CDC-hosted schedule."}}]},"nonClinicalManagement":{"patientEducation":["Explain adult vaccination review in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Family Medicine / Public Health","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"17fa021f-7661-44bf-9e70-1754632b4e9c","title":"Advanced COPD Supportive Care","original_version_id":"17fa021f-7661-44bf-9e70-1754632b4e9c","expected_hash":"2154f0bb35abda77550361d63e4e1af6","source_url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","source_title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","scope":"People with end-stage COPD whose breathlessness is unresponsive to other medical therapy and their families or carers.","content":{"id":"17fa021f-7661-44bf-9e70-1754632b4e9c","title":"Advanced COPD Supportive Care","specialty":"Respiratory Medicine / Palliative Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Advanced airflow limitation causes chronic breathlessness and reduced reserve; anxiety, deconditioning, cardiac disease, anaemia, infection, and environment may amplify distress. Palliative support complements respiratory treatment. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Advanced airflow limitation causes chronic breathlessness and reduced reserve","anxiety, deconditioning, cardiac disease, anaemia, infection, and environment may amplify distress. Palliative support complements respiratory treatment."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Advanced COPD Supportive Care, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Acute severe exacerbation or hypoxaemia","New chest pain, haemoptysis, or unilateral findings","Confusion suggesting hypercapnia","Uncontrolled panic or unsafe home support"]},"differentials":[{"condition":"Heart failure","distinguishingFeatures":"Congestion may coexist."},{"condition":"Pulmonary embolism or pneumothorax","distinguishingFeatures":"Consider acute disproportionate change."},{"condition":"Anaemia, infection, anxiety, deconditioning","distinguishingFeatures":"May amplify breathlessness and be treatable."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review symptom trajectory, inhalers, oxygenation, exacerbations, comorbidities, function and anxiety; targeted tests for new change.","modalityTarget":"Review symptom trajectory, inhalers, oxygenation, exacerbations, comorbidities, function and anxiety; targeted tests for new change. — Advanced COPD Supportive Care","targetCondition":"Advanced COPD Supportive Care","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Assess oxygen/ventilation indications using current respiratory guidance, not breathlessness alone.","modalityTarget":"Assess oxygen/ventilation indications using current respiratory guidance, not breathlessness alone. — Cause, complication, or risk relevant to Advanced COPD Supportive Care","targetCondition":"Cause, complication, or risk relevant to Advanced COPD Supportive Care","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Advanced COPD Supportive Care","targetCondition":"Important alternative to Advanced COPD Supportive Care","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People with end-stage COPD whose breathlessness is unresponsive to other medical therapy and their families or carers. NICE names opioids, benzodiazepines, tricyclic antidepressants, major tranquillisers and oxygen but gives no exact dose, route, frequency, duration or complete contraindication set in these recommendations. Specialist palliative, respiratory and Saudi formulary review is mandatory before any medicine order. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"533c0568-0bc6-4909-813b-501d0e89082c","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, palliative-care recommendations retained from 2004 and linked standards updated 2018","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.2.106 to 1.2.109","primary_source":true}],"selection_rationale":"Unverified scope: People with end-stage COPD whose breathlessness is unresponsive to other medical therapy and their families or carers."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Multidisciplinary symptom and palliative-needs assessment","clinical_question":"Is breathlessness persistent despite optimised disease-directed treatment and what services are needed?","expected_finding":"Refractory breathlessness and patient/family needs may support palliative-team involvement.","decision_rationale":"The NICE section applies medicine considerations only when end-stage COPD breathlessness remains unresponsive and recommends access to multidisciplinary palliative services.","timeframe":"When symptoms remain refractory or needs change"}],"evidence":{"sources":[{"id":"533c0568-0bc6-4909-813b-501d0e89082c","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, palliative-care recommendations retained from 2004 and linked standards updated 2018","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.2.106 to 1.2.109","primary_source":true}],"selection_rationale":"Unverified scope: People with end-stage COPD whose breathlessness is unresponsive to other medical therapy and their families or carers."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Provide access to the full range of multidisciplinary palliative-care services, including hospice admission when appropriate.","timeframe":"According to assessed need"},{"instruction":"Consider an opioid for refractory breathlessness only after other medical therapy has not relieved it and with specialist/local prescribing review.","timeframe":"When clinically appropriate after optimisation"},{"instruction":"Consider benzodiazepines, tricyclic antidepressants, major tranquillisers or oxygen only when appropriate for refractory breathlessness and after individual benefit-risk review.","timeframe":"When clinically appropriate after optimisation"},{"instruction":"Review gaps: NICE names opioids, benzodiazepines, tricyclic antidepressants, major tranquillisers and oxygen but gives no exact dose, route, frequency, duration or complete contraindication set in these recommendations. Specialist palliative, respiratory and Saudi formulary review is mandatory before any medicine order.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"533c0568-0bc6-4909-813b-501d0e89082c","title":"Chronic obstructive pulmonary disease in over 16s: diagnosis and management","issuer":"NICE","edition":"NG115, palliative-care recommendations retained from 2004 and linked standards updated 2018","url":"https://www.nice.org.uk/guidance/ng115/chapter/recommendations","locator":"Recommendations 1.2.106 to 1.2.109","primary_source":true}],"selection_rationale":"Unverified scope: People with end-stage COPD whose breathlessness is unresponsive to other medical therapy and their families or carers."}}]},"nonClinicalManagement":{"patientEducation":["Explain advanced copd supportive care in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Respiratory Medicine / Palliative Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"7c1b7028-68a7-4fdb-ae44-be27da67e5e1","title":"Advanced Dementia and Comfort-Focused Care","original_version_id":"7c1b7028-68a7-4fdb-ae44-be27da67e5e1","expected_hash":"2464114f0f51e05f89f6a13bcac51514","source_url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","source_title":"Dementia: assessment, management and support for people living with dementia and their carers","issuer":"NICE","scope":"People living with advanced or severe dementia, including those approaching the end of life, and their families or carers.","content":{"id":"7c1b7028-68a7-4fdb-ae44-be27da67e5e1","title":"Advanced Dementia and Comfort-Focused Care","specialty":"Geriatrics / Palliative Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Progressive neurodegeneration impairs cognition, communication, mobility, and swallowing. Complications such as infection and aspiration interact with frailty; care decisions should reflect prior wishes and current comfort. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Progressive neurodegeneration impairs cognition, communication, mobility, and swallowing. Complications such as infection and aspiration interact with frailty","care decisions should reflect prior wishes and current comfort."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Advanced Dementia and Comfort-Focused Care, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Acute choking or respiratory distress","Pain, fracture, or untreated infection","Family conflict affecting immediate care","Caregiver burnout or neglect risk"]},"differentials":[{"condition":"Delirium on dementia","distinguishingFeatures":"Acute change warrants reversible-cause assessment."},{"condition":"Depression or medication sedation","distinguishingFeatures":"May worsen function and intake."},{"condition":"Dysphagia from stroke or structural lesion","distinguishingFeatures":"Assess if presentation is abrupt or focal."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Collateral history, pain and swallowing assessment, medication review, hydration/nutrition status and focused exam.","modalityTarget":"Collateral history, pain and swallowing assessment, medication review, hydration/nutrition status and focused exam. — Advanced Dementia and Comfort-Focused Care","targetCondition":"Advanced Dementia and Comfort-Focused Care","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Investigate only when likely to change goal-concordant care; involve speech-language and nutrition teams.","modalityTarget":"Investigate only when likely to change goal-concordant care; involve speech-language and nutrition teams. — Cause, complication, or risk relevant to Advanced Dementia and Comfort-Focused Care","targetCondition":"Cause, complication, or risk relevant to Advanced Dementia and Comfort-Focused Care","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Advanced Dementia and Comfort-Focused Care","targetCondition":"Important alternative to Advanced Dementia and Comfort-Focused Care","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People living with advanced or severe dementia, including those approaching the end of life, and their families or carers. The source provides care principles rather than exact symptom-control prescriptions. Medicine names, doses, routes, frequencies, durations and contraindications require an individualised palliative plan, current care-of-dying guidance and Saudi/local formulary review. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"7657e695-9a38-4252-824f-f57275af61af","title":"Dementia: assessment, management and support for people living with dementia and their carers","issuer":"NICE","edition":"NG97, published 20 June 2018; surveillance review 24 October 2025","url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","locator":"Recommendations 1.9.1 to 1.10.8","primary_source":true}],"selection_rationale":"Unverified scope: People living with advanced or severe dementia, including those approaching the end of life, and their families or carers."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Needs, capacity and anticipatory-care assessment","clinical_question":"What comfort, communication, nutrition, safety and end-of-life needs are present and can the person participate in decisions?","expected_finding":"The assessment informs flexible palliative care, advance planning and best-interest decisions where capacity is absent.","decision_rationale":"NICE recommends needs-based palliative care from diagnosis and anticipatory healthcare planning near end of life.","timeframe":"From diagnosis and whenever needs or prognosis change"},{"test":"Swallow and nutrition safety review","clinical_question":"Can the person eat and drink safely and is specialist swallowing input required?","expected_finding":"Swallowing concern may prompt speech and language therapy involvement.","decision_rationale":"NICE recommends supporting eating and drinking and considering speech and language therapy for safety concerns.","timeframe":"When eating or drinking concerns arise"}],"evidence":{"sources":[{"id":"7657e695-9a38-4252-824f-f57275af61af","title":"Dementia: assessment, management and support for people living with dementia and their carers","issuer":"NICE","edition":"NG97, published 20 June 2018; surveillance review 24 October 2025","url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","locator":"Recommendations 1.9.1 to 1.10.8","primary_source":true}],"selection_rationale":"Unverified scope: People living with advanced or severe dementia, including those approaching the end of life, and their families or carers."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer flexible, needs-based palliative care and use anticipatory healthcare planning when the person is approaching end of life.","timeframe":"From diagnosis and as end of life approaches"},{"instruction":"Balance current medical needs against the harms of hospital admission and consider advance plans and the value of familiar surroundings.","timeframe":"Whenever hospital admission is considered"},{"instruction":"Do not routinely use enteral feeding in severe dementia unless a potentially reversible comorbidity indicates it.","timeframe":"When enteral feeding is considered"},{"instruction":"Review gaps: The source provides care principles rather than exact symptom-control prescriptions. Medicine names, doses, routes, frequencies, durations and contraindications require an individualised palliative plan, current care-of-dying guidance and Saudi/local formulary review.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"7657e695-9a38-4252-824f-f57275af61af","title":"Dementia: assessment, management and support for people living with dementia and their carers","issuer":"NICE","edition":"NG97, published 20 June 2018; surveillance review 24 October 2025","url":"https://www.nice.org.uk/guidance/ng97/chapter/recommendations","locator":"Recommendations 1.9.1 to 1.10.8","primary_source":true}],"selection_rationale":"Unverified scope: People living with advanced or severe dementia, including those approaching the end of life, and their families or carers."}}]},"nonClinicalManagement":{"patientEducation":["Explain advanced dementia and comfort-focused care in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Geriatrics / Palliative Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"1f3a8674-fb1a-4c14-9744-8ae2d3eed686","title":"Advanced Heart Failure Supportive Care","original_version_id":"1f3a8674-fb1a-4c14-9744-8ae2d3eed686","expected_hash":"c9c6b2f1f6f38166f20efe9b8162df57","source_url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","source_title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","scope":"Adults with heart failure whose symptoms are worsening despite optimal specialist treatment, including advance planning and end-of-life support.","content":{"id":"1f3a8674-fb1a-4c14-9744-8ae2d3eed686","title":"Advanced Heart Failure Supportive Care","specialty":"Cardiology / Palliative Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b002","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Progressive pump dysfunction causes congestion, fatigue, and episodic decompensation. Symptom management, planning, and specialist heart-failure treatment can proceed concurrently and adapt to changing goals. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Progressive pump dysfunction causes congestion, fatigue, and episodic decompensation. Symptom management, planning, and specialist heart-failure treatment can proceed concurrently and adapt to changing goals.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Advanced Heart Failure Supportive Care, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Acute decompensation or new ischaemia requiring assessment consistent with goals","Refractory dyspnoea or oedema","Repeated crisis admissions or caregiver exhaustion","Device shock or distressing therapy"]},"differentials":[{"condition":"COPD or infection","distinguishingFeatures":"May coexist and alter breathlessness plan."},{"condition":"Depression/anxiety","distinguishingFeatures":"Can intensify symptom burden and need direct support."},{"condition":"Renal deterioration or anaemia","distinguishingFeatures":"May worsen fatigue and congestion."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review heart-failure phenotype, symptoms, admissions, medicines, renal function, device status and patient priorities.","modalityTarget":"Review heart-failure phenotype, symptoms, admissions, medicines, renal function, device status and patient priorities. — Advanced Heart Failure Supportive Care","targetCondition":"Advanced Heart Failure Supportive Care","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use focused testing when it changes treatment or comfort plan; reconcile advance-care documentation.","modalityTarget":"Use focused testing when it changes treatment or comfort plan; reconcile advance-care documentation. — Cause, complication, or risk relevant to Advanced Heart Failure Supportive Care","targetCondition":"Cause, complication, or risk relevant to Advanced Heart Failure Supportive Care","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Advanced Heart Failure Supportive Care","targetCondition":"Important alternative to Advanced Heart Failure Supportive Care","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with heart failure whose symptoms are worsening despite optimal specialist treatment, including advance planning and end-of-life support. The palliative-care recommendations do not provide exact symptom-control medicine doses, routes, frequencies, durations or contraindications. Current heart-failure therapy, renal function, device management, care-of-dying guidance and Saudi/local formulary requirements need specialist reconciliation before approval. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"147cd1d7-73c4-423f-b7fc-251ff165485d","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.1.3 to 1.1.4, 1.10.5 and 1.12.1 to 1.12.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with heart failure whose symptoms are worsening despite optimal specialist treatment, including advance planning and end-of-life support."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Specialist heart-failure and palliative-needs review","clinical_question":"Are symptoms worsening despite optimal specialist treatment and are palliative services required?","expected_finding":"Unresolved symptom burden may trigger MDT discussion and palliative-needs assessment.","decision_rationale":"NICE recommends discussion with the specialist heart-failure MDT when symptoms worsen despite optimal treatment.","timeframe":"When symptoms worsen or care goals change"},{"test":"Implantable cardioverter-defibrillator benefit-harm review","clinical_question":"Does continued activation remain consistent with current goals of care?","expected_finding":"A documented review may support continuation or advance planning for deactivation.","decision_rationale":"NICE recommends review every 6 months, whenever goals change and during end-of-life advance planning.","timeframe":"Every 6 months, on goal changes, and during advance care planning"}],"evidence":{"sources":[{"id":"147cd1d7-73c4-423f-b7fc-251ff165485d","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.1.3 to 1.1.4, 1.10.5 and 1.12.1 to 1.12.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with heart failure whose symptoms are worsening despite optimal specialist treatment, including advance planning and end-of-life support."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss palliative needs with the specialist heart-failure MDT and consider a formal palliative-needs assessment when symptoms worsen despite optimal treatment.","timeframe":"At recognition of worsening refractory symptoms"},{"instruction":"Offer the person and family or carers access to professionals with palliative-care skills within the heart-failure team.","timeframe":"According to assessed need"},{"instruction":"Do not offer long-term home oxygen solely for advanced heart failure; assess separate comorbid indications if present.","timeframe":"When home oxygen is considered"},{"instruction":"Review gaps: The palliative-care recommendations do not provide exact symptom-control medicine doses, routes, frequencies, durations or contraindications. Current heart-failure therapy, renal function, device management, care-of-dying guidance and Saudi/local formulary requirements need specialist reconciliation before approval.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"147cd1d7-73c4-423f-b7fc-251ff165485d","title":"Chronic heart failure in adults: diagnosis and management","issuer":"NICE","edition":"NG106, last updated 3 September 2025","url":"https://www.nice.org.uk/guidance/ng106/chapter/recommendations","locator":"Recommendations 1.1.3 to 1.1.4, 1.10.5 and 1.12.1 to 1.12.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with heart failure whose symptoms are worsening despite optimal specialist treatment, including advance planning and end-of-life support."}}]},"nonClinicalManagement":{"patientEducation":["Explain advanced heart failure supportive care in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Cardiology / Palliative Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}}]$population$)
